import './styles.css';

type Page = 'overview' | 'projects' | 'notes';
type Project = {id: string; title: string; description: string; category: string; tone: string; progress: number; date: string; members: string[]};
type Note = {id: string; title: string; content: string; date: string};
const initialProjects: Project[] = [
