  return <ThemeProvider theme={theme}><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} hideCollapseButton hideSectionDividers logo={{text:()=> <span className=\"brand-name\">орбита<span className=\"brand-dot\">.</span></span>,icon:OrbitalLogo,iconSize:34,href:'#overview'}} aboveMenuContent={compact?<div className=\"compact-spacer\"/>:<div className=\"sidebar-intro\"><div className=\"workspace\"><span className=\"workspace-icon\">А</span><div><strong>Моё пространство</strong><small>Личный аккаунт</small></div><Icon data={ChevronDown} size={14}/></div><span className=\"navigation-label\">ПРОСТРАНСТВО</span></div>} menuItems={[{id:'overview',title:'Обзор',icon:House,current:page==='overview',href:'#overview',menuItemAriaProps:{'aria-current':page==='overview'?'page':undefined}},{id:'projects',title:'Проекты',icon:Folder,current:page==='projects',href:'#projects',rightAdornment:"'!compact?<span className="nav-count">{projects.length}</span>:undefined,menuItemAriaProps:{'"'aria-current':page==='projects'?'page':undefined}},{id:'notes',title:'Заметки',icon:FileText,current:page==='notes',href:'#notes',menuItemAriaProps:{'aria-current':page==='notes'?'page':undefined}}]} renderFooter={()=> <div className={"'`sidebar-footer ${compact?'"'is-compact':''}"'`}>{!compact&&<div className="sidebar-quote"><span>✧</span><Text variant="subheader-2">У больших идей<br/>есть своё место.</Text><p>И оно прямо здесь.</p><div className="quote-orbit"/></div>}<Button view="flat" width="max" className="help-button" onClick={()=>setModal('"'help')} aria-label=\"Помощь и поддержка\"><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button><div className=\"theme-row\"><Icon data={theme==='dark'?Moon:Sun} size={18}/>{"'!compact&&<span>Тёмная тема</span>}<Switch size="m" checked={theme==='"'dark'} onUpdate={checked=>setTheme(checked?'dark':'light')} aria-label=\"Тёмная тема\"/></div>{"'!compact&&<div className="sidebar-profile"><Avatar n