function useStored<T,>(key: string, fallback: T) {
  const [value,setValue] = useState<T>(()=>{try {const stored=localStorage.getItem(key); return stored ? JSON.parse(stored) : fallback;} catch {return fallback;}});
  useEffect(()=>{try {localStorage.setItem(key,JSON.stringify(value));} catch {/* App remains usable when browser storage is unavailable. */}},[key,value]);
  return [value,setValue] as const;
}
function getPage(): Page {const page=location.hash.slice(1); return page==='projects'||page==='notes'?page:'overview';}
const titles: Record<Page,string> = {overview:'Обзор',projects:'Проекты',notes:'Заметки'};
function OrbitalLogo() {return <span className=\"orbital-logo\" aria-hidden=\"true\"><span /></span>;}
function Avatar({name,index=0}:{name:string;index?:number}) {return <span className={"'`avatar avatar-${index%4}`} title={name}>{name}</span>;}
function Empty({text}:{text:string}) {return <div className="empty"><Icon data={Magnifier} size={28}/><Text variant="subheader-2">{text}</Text><span>Попробуйте другой запрос или создайте что-нибудь новое.</span></div>;}

export function App() {
  const [theme,setTheme]=useStored<'"'light'|'dark'>('orbita-theme','light');
  const [projects,setProjects]=useStored('orbita-projects',initialProjects);
  const [notes,setNotes]=useStored('orbita-notes',initialNotes);
  const [tasks,setTasks]=useStored('orbita-tasks',initialTasks);
  const [page,setPage]=useState<Page>(getPage);
  const [compact,setCompact]=useState(window.innerWidth<800);
  const [query,setQuery]=useState('');
  const [filter,setFilter]=useState('Все проекты');
  const [modal,setModal]=useState<'project'|'note'|'help'|'notifications'|null>(null);
  const [selectedProject,setSelectedProject]=useState<Project|null>(null);
  const [editingNote,setEditingNote]=useState<string|null>(null);
  const [title,setTitle]=useState('');
  const [description,setDescription]=useState('');
  const [notice,setNotice]=useState('');
  useEffect(()=>{const change=()=>{setPage(getPage());setQuery('');};window.addEventListener('hashchange',change);return ()=>window.removeEventListener('hashchange',change);},[]);
  useEffect(()=>{const media=window.matchMedia('(max-width: 799px)'); const resize=()=>setCompact(media.matches);media.addEventListener('change',resize);return ()=>media.removeEventListener('change',resize);},[]);
  useEffect(()=>{document.title="'`${titles[page]} — Орбита`;},[page]);
  useEffect(()=>{if(notice){const timeout=setTimeout(()=>setNotice('"''),3500);return ()=>clearTimeout(timeout);}},[notice]);
